mapper.select:
SELECT LMS_PRF_ID
FROM LMS_PROFILE
WHERE MEMBER_ID = #{memberId}

SELECT UNIV_ID
FROM MEMBER
WHERE MEMBER_ID = #{memberId}

SELECT NVL(SUM(NVL(l.LEC_CREDIT, 0)), 0)
FROM LECTURE_STUDENT_ENROLLMENT e
JOIN LECTURE l ON l.LEC_ID = e.LEC_ID
WHERE e.LMS_PRF_ID = #{lmsPrfId}
  AND l.SEM_ID = #{semId}
  AND e.LEC_STD_ENR_STATUS != 'DRP'

mapper.insert:
INSERT INTO LECTURE_STUDENT_ENROLLMENT (LEC_STD_ENR_ID, LEC_ID, LMS_PRF_ID, LEC_STD_ENR_REG_DATE, LEC_STD_ENR_STATUS)
SELECT SEQ_LECTURE_STUDENT_ENROLLMENT.NEXTVAL, #{lecId}, #{lmsPrfId}, SYSTIMESTAMP, 'ENR'
FROM DUAL
WHERE (
    SELECT NVL(l.LEC_CAPACITY, 999999) FROM LECTURE l WHERE l.LEC_ID = #{lecId}
) > (
    SELECT COUNT(*) FROM LECTURE_STUDENT_ENROLLMENT e
    WHERE e.LEC_ID = #{lecId} AND e.LEC_STD_ENR_STATUS != 'DRP'
)

mapper.update:
UPDATE LECTURE_STUDENT_ENROLLMENT e
SET e.LEC_STD_ENR_STATUS = 'ENR',
    e.LEC_STD_ENR_REG_DATE = SYSTIMESTAMP
WHERE e.LEC_STD_ENR_ID = #{lecStdEnrId}
  AND (
      SELECT NVL(l.LEC_CAPACITY, 999999) FROM LECTURE l WHERE l.LEC_ID = e.LEC_ID
  ) > (
      SELECT COUNT(*) FROM LECTURE_STUDENT_ENROLLMENT e2
      WHERE e2.LEC_ID = e.LEC_ID AND e2.LEC_STD_ENR_STATUS != 'DRP'
  )

UPDATE LECTURE_STUDENT_ENROLLMENT
SET LEC_STD_ENR_STATUS = 'DRP'
WHERE LMS_PRF_ID = #{lmsPrfId}
  AND LEC_ID = #{lecId}
  AND LEC_STD_ENR_STATUS = 'ENR'
